 domain_math_.blocks=core.model.blocks;domain_math_.materials=core.model.materials;domain_math_.blocks[0].values.resize(32);physical_=domain_math_.physical_specs();
 for(std::size_t bi=0;bi<core.model.blocks.size();++bi){const auto&b=core.model.blocks[bi];if(b.name.rfind("ice/half_circle/",0)==0)for(int type:{13,14}){EventPhysicalConstraint c;c.id=b.name+"/finite_arc_domain_"+std::to_string(type);c.type=type;c.block_ids={0,int(bi)};physical_.push_back(c);}if(b.name.rfind("ice/polyline/",0)==0){if(b.values.size()%2)throw std::runtime_error("ice polyline shape");for(std::size_t k=0;k<b.values.size();k+=2){EventPhysicalConstraint c;c.id=b.name+"/vertex_"+std::to_string(k/2)+"_in_rink";c.type=7;c.index=int(k);c.block_ids={0,int(bi)};physical_.push_back(c);}}}
 for(std::size_t bi=0;bi<core.model.blocks.size();++bi){const auto&b=core.model.blocks[bi];if(b.name.rfind("print_component/polyline/",0)==0){if(b.values.size()%2)throw std::runtime_error("shared print polyline coordinate shape");for(std::size_t k=1;k<b.values.size();k+=2)for(int direction:{0,1}){EventPhysicalConstraint c;c.id=b.name+"/height_"+std::to_string(k/2)+"/"+std::to_string(direction);c.type=15;c.index=int(k);c.direction=direction;c.block_ids={0,int(bi)};physical_.push_back(c);}EventPhysicalConstraint c;c.id=b.name+"/finite_course_span";c.type=17;c.index=int(b.values.size());c.block_ids={0,int(bi)};physical_.push_back(c);}if(b.name.rfind("print_component/ellipse/",0)==0){if(b.values.size()!=5)throw std::runtime_error("shared print ellipse coordinate shape");for(int k=0;k<5;++k){EventPhysicalConstraint c;c.id=b.name+"/ellipse_domain_"+std::to_string(k);c.type=16;c.index=k;c.block_ids={0,int(bi)};physical_.push_back(c);}}}
 for(std::size_t i=0;i<core.packet.rows.size();++i){const auto&r=core.packet.rows[i];ObservationSpec s;s.key=r.source_dataset_id+":"+r.source_row_id+":"+r.shot_id+":"+std::to_string(r.pts);s.source_uv=r.uv;s.E={r.E*r.E,0,0,r.E*r.E};s.active=r.active;if(!s.active){s.exclusion_reason="joint versioned admission/locked role";s.exclusion_id=core.packet.source_hash+":"+std::to_string(i);}else{active_.push_back(i);schema_.inequality_ids.push_back("pixel/"+s.key);if(r.kind!=1)station_rows_.push_back(i);equalities_.push_back({i,-1});schema_.equality_ids.push_back("RS/"+s.key);for(int k=0;k<3;++k)native_domains_.push_back({i,k});const auto&path=core.model.materials.at(r.material).paths.at(r.path);if(path.kind==2||path.kind==3||path.kind==6||path.kind==7)native_domains_.push_back({i,3});native_domains_.push_back({i,4});if(!r.source_station_intervals.empty()||core.model.station_intervals(r.material,r.path)!=std::vector<std::array<double,2>>{{0.,1.}})native_domains_.push_back({i,7});if(r.width_block>=0){native_domains_.push_back({i,5});if(path.kind==1||path.kind==4)native_domains_.push_back({i,6});}}
  if(r.query){s.semantics=ObservationSemantics::kGenuineProfile;s.profile_normal=r.normal;s.profile_radius_px=r.E;s.original_curved_query=true;s.profile_alpha_lower_px=r.query->alpha.front();s.profile_alpha_upper_px=r.query->alpha.back();if(r.active){profile_rows_.push_back(i);for(int k=0;k<2;++k){equalities_.push_back({i,k});schema_.equality_ids.push_back("frozen_query_"+std::to_string(k)+"/"+s.key);}}}observations_.push_back(s);}
 std::set<std::string> relation_ids;std::map<std::string,std::size_t> relation_blocks;for(std::size_t i=0;i<core.model.blocks.size();++i)relation_blocks[core.model.blocks[i].name]=i;
 for(const auto&d:core.model.source_json.value("physical_equalities",eventio::Json::array())){HardEquality h;h.id=d.at("id");if(!relation_ids.insert(h.id).second)throw std::runtime_error("duplicate hard physical relation "+h.id);if(d.value("expression_kind",std::string("linear"))!="linear")throw std::runtime_error("unsupported hard physical expression "+h.id);h.functor.rhs=d.at("rhs");h.functor.evaluation_scale=d.value("evaluation_scale",10000.);if(!std::isfinite(h.functor.evaluation_scale)||h.functor.evaluation_scale<=0)throw std::runtime_error("invalid hard relation numerical scale "+h.id);if(!std::isfinite(h.functor.rhs)||!d.contains("source_refs")||d.at("source_refs").empty())throw std::runtime_error("hard physical relation lacks finite/source binding "+h.id);for(const auto&t:d.at("terms")){std::size_t bi=t.at("block").is_string()?relation_blocks.at(t.at("block").get<std::string>()):t.at("block").get<std::size_t>();int index=t.at("index");double c=t.at("coefficient");if(index<0||index>=int(core.model.blocks.at(bi).values.size())||!std::isfinite(c)||c==0)throw std::runtime_error("hard physical term invalid "+h.id);auto it=std::find(h.ids.begin(),h.ids.end(),bi);int slot=int(it-h.ids.begin());if(it==h.ids.end())h.ids.push_back(bi);h.functor.terms.push_back({slot,index,c});}if(h.functor.terms.empty())throw std::runtime_error("empty hard physical relation "+h.id);schema_.equality_ids.push_back("physical_relation/"+h.id);hard_equalities_.push_back(std::move(h));}
 for(std::size_t ri=0;ri<core.model.rigs.size();++ri){std::array<double,2>h={INFINITY,-INFINITY},box={INFINITY,-INFINITY};const auto&rig=core.model.rigs[ri];for(const auto&shot:core.model.shots)if(shot.rig_id==rig.id)for(std::size_t i=0;i<shot.control_sources.size();++i){int b=shot.control_sources[i],offset=shot.control_offsets[i];const auto&p=core.model.blocks[b];h[0]=std::min(h[0],p.values[offset+2]);h[1]=std::max(h[1],p.values[offset+2]);box[0]=std::min(box[0],p.lower[offset+2]);box[1]=std::max(box[1],p.upper[offset+2]);for(int upper:{0,1})zoom_bounds_.push_back({ri,b,offset,upper,"rig/"+rig.id+"/whole_cubic_hull/"+shot.id+"/control_"+std::to_string(i)+"/"+std::to_string(upper)});}if(!std::isfinite(h[0])||!std::isfinite(h[1])||!std::isfinite(box[0])||!std::isfinite(box[1]))throw std::runtime_error("missing finite full zoom hull "+rig.id);zoom_enclosures_.push_back(h);zoom_box_.push_back(box);}
 schema_.pixel_count=active_.size();for(const auto&c:physical_)schema_.inequality_ids.push_back(c.id);for(const auto&d:native_domains_)schema_.inequality_ids.push_back("native_domain/"+std::to_string(d.row)+"/"+std::to_string(d.kind));
 for(const auto&z:zoom_bounds_)schema_.inequality_ids.push_back(z.id);for(const auto&rig:core.model.rigs)for(int k:{0,1})schema_.inequality_ids.push_back("rig/"+rig.id+"/whole_zoom_Brown_certificate/"+std::to_string(k));
