  auto scalar=[&](const std::string&prefix,std::vector<double>&d){if(a.name.rfind(prefix,0)!=0)return false;if(a.values.size()!=1)throw std::runtime_error("nonscalar auxiliary");const auto i=std::stoull(a.name.substr(prefix.size()));d.at(i)=b.values[0]-a.values[0];return true;};
